SELECT  
WHERE r.tenant_id=#{tenant} AND r.id > #{q.after}
AND r.business_no=#{q.filters.refundNo}r.refund_no=#{q.filters.refundNo}
AND o.business_no=#{q.filters.orderNo}r.order_no=#{q.filters.orderNo}
AND 
  r.approval_business_no=#{q.filters.approvalNo}
  r.approval_ref=#{q.filters.approvalNo}

AND r.member_id=#{q.filters.memberId}
AND r.status=#{q.filters.status}
AND r.created_at >= #{q.createdFrom} AND r.created_at < #{q.createdTo}
AND r.approval_deadline >= #{q.filters.approvalDeadlineFrom} AND r.approval_deadline < #{q.filters.approvalDeadlineTo}
ORDER BY r.id ASC LIMIT #{q.fetchLimit}
